import { useState } from 'react';
import { MessageSquareQuote, Quote, TrendingDown, Coins, ShieldAlert, ListChecks, ChevronDown, Sparkles } from 'lucide-react';
import type { Brief } from '../types';
import { FDC } from '../lib/brand';

/**
 * The AI negotiation brief — the single highest-value asset: a ready "what to say & ask"
 * script per vendor (headline, opening line, price ask, payment ask) with the evidence and
 * risks one click away. Generated by Claude from the real Probe42 + SAP data (see briefs.json).
 * `dense` renders the compact takeaway used to lead the full-profile modal.
 */
export function NegotiationBrief({ brief, dense = false }: { brief: Brief; dense?: boolean }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="overflow-hidden rounded-xl border border-fdc-green/25 bg-fdc-green/[0.04]">
      <div className="flex items-center gap-1.5 border-b border-fdc-green/15 bg-fdc-green/[0.07] px-3 py-2">
        <MessageSquareQuote size={14} className="text-fdc-green" strokeWidth={2.3} />
        <span className="text-[12px] font-bold uppercase tracking-wide text-fdc-green">What to say &amp; ask</span>
        <span className="ml-auto inline-flex items-center gap-1 text-[10px] font-semibold text-fdc-grey">
          <Sparkles size={11} className="text-fdc-gold-dark" /> AI brief
        </span>
      </div>

      <div className="space-y-2.5 p-3">
        {/* strategic headline */}
        <p className="text-[12.5px] font-semibold leading-snug text-fdc-ink">{brief.headline}</p>

        {/* opening line — the thing to actually say */}
        <div className="rounded-lg border-l-[3px] border-fdc-gold bg-white px-3 py-2">
          <div className="mb-0.5 flex items-center gap-1 text-[10px] font-bold uppercase tracking-wide text-fdc-grey">
            <Quote size={11} className="text-fdc-gold-dark" /> Your opening line
          </div>
          <p className="text-[12.5px] italic leading-snug text-fdc-slate">“{brief.suggestedOpeningLine}”</p>
        </div>

        {/* the two asks */}
        <div className="grid gap-2 sm:grid-cols-2">
          <Ask icon={TrendingDown} color={FDC.green} label="Ask on price" summary={brief.priceAsk.summary} detail={brief.priceAsk.target} />
          <Ask icon={Coins} color={FDC.blue} label="Ask on payment" summary={brief.paymentTermAsk.summary} detail={brief.paymentTermAsk.cashImpact} />
        </div>

        {/* proof-on-click: evidence, leverage & risks (hidden by default to keep it a 1-screen takeaway) */}
        {!dense && (
          <>
            <button
              onClick={() => setOpen((v) => !v)}
              className="flex w-full items-center justify-between rounded-lg border border-black/[0.07] bg-white px-3 py-1.5 text-[11.5px] font-semibold text-fdc-slate transition hover:bg-black/[0.02] focus-ring"
            >
              <span className="inline-flex items-center gap-1.5"><ListChecks size={13} className="text-fdc-green" /> Why we can push &amp; what to watch</span>
              <ChevronDown size={14} className={`text-fdc-grey transition ${open ? 'rotate-180' : ''}`} />
            </button>
            {open && (
              <div className="space-y-2.5 rounded-lg bg-white px-3 py-2.5">
                {brief.priceAsk.basis && <p className="text-[11.5px] leading-snug text-fdc-slate"><b className="text-fdc-ink">Price basis:</b> {brief.priceAsk.basis}</p>}
                {brief.financialLeverage && <p className="text-[11.5px] leading-snug text-fdc-slate"><b className="text-fdc-ink">Financial leverage:</b> {brief.financialLeverage}</p>}
                {brief.evidence?.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    {brief.evidence.map((e, i) => (
                      <span key={i} className="rounded-md bg-fdc-offwhite px-1.5 py-0.5 text-[10.5px] text-fdc-slate" title={e.point}>
                        <b className="tnum text-fdc-ink">{e.figure}</b>
                      </span>
                    ))}
                  </div>
                )}
                {brief.risks?.length > 0 && (
                  <div>
                    <div className="mb-1 flex items-center gap-1 text-[10px] font-bold uppercase tracking-wide text-fdc-orange"><ShieldAlert size={11} /> Watch-outs</div>
                    <ul className="space-y-1">
                      {brief.risks.map((r, i) => <li key={i} className="flex gap-1.5 text-[11px] leading-snug text-fdc-slate"><span className="mt-[5px] h-1 w-1 shrink-0 rounded-full bg-fdc-orange" />{r}</li>)}
                    </ul>
                  </div>
                )}
              </div>
            )}
          </>
        )}

        <p className="text-[10px] leading-snug text-fdc-grey">{brief.approvalNote}</p>
      </div>
    </div>
  );
}

function Ask({ icon: Icon, color, label, summary, detail }: { icon: typeof Coins; color: string; label: string; summary: string; detail: string }) {
  return (
    <div className="rounded-lg border border-black/[0.07] bg-white p-2.5">
      <div className="mb-1 flex items-center gap-1 text-[10px] font-bold uppercase tracking-wide" style={{ color }}>
        <Icon size={12} /> {label}
      </div>
      <p className="text-[12px] font-semibold leading-snug text-fdc-ink">{summary}</p>
      {detail && <p className="mt-1 text-[11px] leading-snug text-fdc-grey">{detail}</p>}
    </div>
  );
}
